test:
db = VersionedGetWhenDatabase()
db.write('job', 2, {'state': 'draft'})
for call in (lambda: db.write('job', 2, {'state': 'ready'}), lambda: db.write('job', 1, {'state': 'ready'}), lambda: db.write('job', 3, {}), lambda: db.write('job', 3, {'state': []}), lambda: db.history('job', 5, 4), lambda: db.get_when('job', '', 'draft')):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
assert db.get_at('job', 2)['fields']['state'] == 'draft'
try:
    db.get_at('missing', 1)
    raise AssertionError('expected KeyError')
except KeyError:
    pass
